-- Opsional: jalankan di Neon SQL Editor. Aplikasi juga membuat tabel otomatis.
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,display TEXT NOT NULL,email TEXT UNIQUE NOT NULL,pass_hash TEXT NOT NULL,default_mode TEXT NOT NULL DEFAULT 'MEDIUM',instructions TEXT NOT NULL DEFAULT '',answer_length TEXT NOT NULL DEFAULT 'sedang',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id SERIAL PRIMARY KEY,conv_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,mode TEXT,file_id UUID,att TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS files(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,conv_id UUID REFERENCES conversations(id) ON DELETE CASCADE,kind TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,data TEXT NOT NULL,meta TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reset_tokens(token_hash TEXT PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
